// B. Four lanes = four roles; six hand-offs; two decisions with both branches labelled.
const SWIMLANE = `
@startuml
|User|
start
:Submit ticket with category;
|QuickFix|
:Compute ticket priority;
:Notify helpdesk queue;
|Helpdesk Agent|
:Triage ticket;
if (Agent can solve it directly?) then (yes)
  :Resolve ticket;
else (no)
  :Assign ticket to technician;
  |Technician|
  :Diagnose and fix problem;
  :Mark ticket resolved;
endif
|QuickFix|
:Ask user to confirm resolution;
|User|
if (Problem solved?) then (yes)
  :Confirm resolution;
else (no)
  :Reopen ticket;
endif
stop
@enduml
`;

// C1. Write all 8 columns first, then fill each action from BR-07.
const DECISION_TABLE = [
  { moreThan10Users: 'Y', blocksTeaching: 'Y', workaround: 'Y', priority: 'P1' },
  { moreThan10Users: 'Y', blocksTeaching: 'Y', workaround: 'N', priority: 'P1' },
  { moreThan10Users: 'Y', blocksTeaching: 'N', workaround: 'Y', priority: 'P3' },
  { moreThan10Users: 'Y', blocksTeaching: 'N', workaround: 'N', priority: 'P2' },
  { moreThan10Users: 'N', blocksTeaching: 'Y', workaround: 'Y', priority: 'P3' },
  { moreThan10Users: 'N', blocksTeaching: 'Y', workaround: 'N', priority: 'P2' },
  { moreThan10Users: 'N', blocksTeaching: 'N', workaround: 'Y', priority: 'P4' },
  { moreThan10Users: 'N', blocksTeaching: 'N', workaround: 'N', priority: 'P3' },
];
// C2. Only YYY and YYN share an action (P1) and differ in one condition ⇒ merge into YY- ⇒ 7 columns.
const REDUCED = { columns: 7, merged: { moreThan10Users: 'Y', blocksTeaching: 'Y', workaround: '-', priority: 'P1' } };
